    def diff(
        self,
        session_id: SessionID,
        *,
        from_: SessionMessageID | NotGiven | None = NOT_GIVEN,
        to: SessionMessageID | NotGiven | None = NOT_GIVEN,
        context: int | NotGiven | None = NOT_GIVEN,
        extra_headers: Headers | None = None,
        extra_query: Query | None = None,
        extra_body: Body | None = None,
        timeout: Timeout | NotGiven = NOT_GIVEN,
    ) -> builtins.list[FileDiffInfo]:
        """Diff session turns.

        Structured per-file diffs of the files a turn changed. A turn runs from the first prompt after the session was last idle until its next idle marker, so prompts steered in while it was busy belong to the same turn; `to` extends the range through a later turn. Compares the range's first recorded snapshot with its last; a step still running in the active session compares against the working copy. Ranges that span a location change are rejected. In sessions without any idle marker, a prompt's turn spans until the next user message.

        Args:
          from_: User message whose turn to diff. Defaults to the turn of the newest user message.
          to: Later user message whose turn ends the range. Defaults to the turn of `from` alone.
          context: Unchanged lines around each hunk. Omit for full-file patches.

        Raises:
          InvalidRequestError: The server answered 400.
          UnauthorizedError: The server answered 401.
          MessageNotFoundError: The server answered 404.
          SessionNotFoundError: The server answered 404.
          LocationNotFoundError: The server answered 404.
          UnknownError: The server answered 500.

        ``GET /api/session/:sessionID/diff``
        """
        return cast(
            "builtins.list[FileDiffInfo]",
            self._client.request(
                RequestOptions(
                    method="GET",
                    path=f"/api/session/{encode_path_segment(session_id)}/diff",
                    query={"from": from_, "to": to, "context": context},
                    extra_headers=extra_headers,
                    extra_query=extra_query,
                    extra_body=extra_body,
                    timeout=timeout,
                ),
                response_type="builtins.list[FileDiffInfo]",
                unwrap=True,
            ),
        )

